
import json
import os
import ipaddress
from datetime import datetime

PROJECT_DIR = os.path.dirname(
    os.path.dirname(os.path.abspath(__file__))
)

# Read traffic generated by the mock API
INPUT_FILE = os.path.join(
    PROJECT_DIR, "logs", "traffic.jsonl"
)

OUTPUT_FILE = os.path.join(
    PROJECT_DIR, "logs", "parsed_events.json"
)


def parse_event(event):
    """Validate and organize one API traffic event."""

    required = [
        "method",
        "path",
        "source_ip",
        "status_code",
        "timestamp"
    ]

    for field in required:
        if field not in event:
            raise ValueError("Missing field: " + field)

    method = event["method"].upper()

    if method not in ["GET", "POST", "PUT", "DELETE", "PATCH"]:
        raise ValueError("Invalid HTTP method")

    path = event["path"]

    if not isinstance(path, str) or not path.startswith("/"):
        raise ValueError("Invalid endpoint path")

    status = event["status_code"]

    if (
        not isinstance(status, int)
        or isinstance(status, bool)
        or not 100 <= status <= 599
    ):
        raise ValueError("Invalid HTTP status code")

    try:
        ipaddress.ip_address(event["source_ip"])
    except (ValueError, TypeError):
        raise ValueError("Invalid source IP address")

    try:
        datetime.fromisoformat(event["timestamp"])
    except (ValueError, TypeError):
        raise ValueError("Invalid timestamp format")

    return {
        "method": method,
        "endpoint": path,
        "source_ip": event["source_ip"],
        "status_code": status,
        "timestamp": event["timestamp"],
        "request_body": event.get("request_body"),
        "authenticated_user_id": event.get(
            "authenticated_user_id"
        ),
        "object_owner_id": event.get("object_owner_id"),
        "route_template": event.get("route_template"),
        "documented": event.get("documented")
    }


def load_events(file_path):
    """Load a JSON array or JSON Lines file."""

    with open(file_path, "r", encoding="utf-8") as file:
        content = file.read().strip()

    if not content:
        return []

    if file_path.lower().endswith(".jsonl"):
        events = []

        for line_number, line in enumerate(
            content.splitlines(), start=1
        ):
            try:
                event = json.loads(line)

                if isinstance(event, dict):
                    events.append(event)
                else:
                    print(
                        "Skipping non-object on line",
                        line_number
                    )

            except json.JSONDecodeError as error:
                print(
                    "Skipping invalid JSON on line",
                    line_number,
                    error
                )

        return events

    data = json.loads(content)

    if not isinstance(data, list):
        raise ValueError("Input must contain a JSON list")

    return data


def main():
    try:
        events = load_events(INPUT_FILE)

        parsed_events = []
        skipped = 0

        for event in events:
            try:
                parsed = parse_event(event)
                parsed_events.append(parsed)
                print("Parsed:", parsed)

            except (ValueError, AttributeError, TypeError) as error:
                skipped += 1
                print("Skipping invalid event:", error)

        os.makedirs(
            os.path.dirname(OUTPUT_FILE),
            exist_ok=True
        )

        with open(OUTPUT_FILE, "w", encoding="utf-8") as file:
            json.dump(parsed_events, file, indent=4)

        print("\nPARSER SUMMARY")
        print("--------------")
        print("Total input events:", len(events))
        print("Successfully parsed:", len(parsed_events))
        print("Skipped invalid events:", skipped)
        print("Output saved to:", OUTPUT_FILE)

    except (OSError, json.JSONDecodeError, ValueError) as error:
        print("Parser error:", error)


if __name__ == "__main__":
    main()
